# END EMBEDDED OPENSCAD BACKEND

_EMBEDDED_OPENSCAD_ROOT = None


def _load_embedded_openscad():
    global _EMBEDDED_OPENSCAD_ROOT
    if _EMBEDDED_OPENSCAD_ROOT is None:
        if not _EMBEDDED_OPENSCAD_GZIP.strip():
            raise RuntimeError("the embedded OpenSCAD backend is not bundled")
        root = Path(tempfile.mkdtemp(prefix="orcad-openscad-backend-"))
        with zipfile.ZipFile(io.BytesIO(gzip.decompress(base64.b64decode(_EMBEDDED_OPENSCAD_GZIP)))) as archive:
            for info in archive.infolist():
                target = (root / info.filename).resolve()
                if root not in target.parents:
                    raise RuntimeError("invalid embedded OpenSCAD backend path")
                if info.is_dir():
                    target.mkdir(parents=True, exist_ok=True)
                else:
                    target.parent.mkdir(parents=True, exist_ok=True)
                    target.write_bytes(archive.read(info))
        sys.path.insert(0, str(root))
        sys.modules.pop("openscad", None)
        _EMBEDDED_OPENSCAD_ROOT = root
    return importlib.import_module("openscad")


